    fn default() -> Block<'a> {
        Block {
            titles: Vec::new(),
            borders: Borders::NONE,
            border_style: Style::default(),
            border_type: BorderType::Plain,
            style: Style::default(),
            padding: Padding::zero(),
        }
    }
}

